// https://www.shadertoy.com/view/4dS3Wd\n        float noise (vec2 st) {\n            vec2 i = floor(st);\n            vec2 f = fract(st);\n\n            // Four corners in 2D of a tile\n            float a = random(i);\n            float b = random(i + vec2(1.0, 0.0));\n            float c = random(i + vec2(0.0, 1.0));\n            float d = random(i + vec2(1.0, 1.0));\n\n            vec2 u = f * f * (3.0 - 2.0 * f);\n\n            return mix(a, b, u.x) +\n                    (c - a)* u.y * (1.0 - u.x) +\n                    (d - b) * u.x * u.y;\n        }\n\n        float fbm (vec2 st, vec2 parallax, int octaveCount, float intens) {\n            // Initial values\n            float value = 0.;\n            float amplitude = 0.5;\n            float frequency = 0.;\n            //\n            // Loop of octaves\n            for (int i = 0; i < octaveCount; i++) {\n                value += amplitude * noise(st);\n                st *= 2.0;\n                st += parallax;\n                amplitude *= intens;\n            }\n            return value;\n        }\n\n\n        vec2 rand2v(vec2 co) {\n            return vec2(noise(co),noise(co+vec2(613.312,736.019)));\n        }\n\n        void main() {\n            vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);\n\n            vec2 st = acLayerNorm.st;\n            st.x *= acLayerSize.x/acLayerSize.y;\n            st -= vec2(0.5,0.5);\n            st -= (position*vec2(1.0,-1.0)/1000.0);\n            st /= (scale*0.07);\n\n            vec2 tile = floor(st);\n            vec2 tpart = fract(st);\n\n            float maxDist = 100.0;\n            vec2 nearestTile = vec2(0.0,0.0);\n            float nearest_k = 0.;\n\n            int densitySteps = int(max(1.0,density-10.0));\n            float threshold = min(1.0,density/11.0);\n\n            float actualPhase = phase * 6.28318;\n\n            for( int i=-1; i<=1; i++ ) {\n                for( int j=-1; j<=1; j++ ) {\n                    vec2 checkTileOffs = vec2(float(i),float(j));\n                    for( int k=0; k<densitySteps; k++ ) {\n                        vec2 p = rand2v(tile + vec2(523.135,621.265)*float(k) + checkTileOffs + vec2(123.215,272.055)*seed);\n                        p = 0.5 + (0.5*sin(actualPhase + 6.2831*p)*max(0.00001,slack));\n                        float dist = length(checkTileOffs + p - tpart);\n                        vec2 tileId = checkTileOffs + tile;\n                        float flk = float(k);\n                        float ck = random(tileId + vec2(flk,-flk) + vec2(541.117,163.713)*(seed+0.1));\n                        if( dist < maxDist && ck<=threshold ) {\n                            maxDist = dist;\n                            nearest_k = float(k);\n                            nearestTile = tileId;\n                        }\n                    }\n                }\n            }\n\n            float colorPct =  random(nearestTile + vec2(nearest_k,-nearest_k) + vec2(721.117,433.215)*seed);\n\n            float intensity = smoothstep(1.0-radius,1.0-(radius*(1.0-feather)),1.-maxDist);\n\n            //intensity *= random(nearestTile + vec2(nearest_k,-nearest_k) + vec2(541.117,163.713)*seed) > threshold ? 0.0 : 1.0;\n\n            vec4 over = texColor * fill;\n            vec4 rcolor = mix(color,color2,colorPct)*intensity*texColor.a;\n\n            vec4 result;\n            if( blendMode==1 ) {\n                result = vec4((texColor.rgb/texColor.a)*(rcolor.rgb/rcolor.a),1.0) * rcolor.a * texColor.a;\n                result = clamp(result,0.0,1.0);\n                result = result+(over*(1.0-result.a));\n                result = clamp(result,0.0,1.0);\n            } else if( blendMode==2 ) {\n                result = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-(rcolor.rgb/rcolor.a))),1.0) * rcolor.a * texColor.a;\n                result = clamp(result,0.0,1.0);\n                result = result+(over*(1.0-result.a));\n                result = clamp(result,0.0,1.0);\n            } else {\n                result = rcolor+(over*(1.0-rcolor.a));\n            }\n            gl_FragColor = mix(over,result,alpha);\n\n\n            //gl_FragColor = result+(over*(1.0-result.a));\n        }\n\n    "}],"scripts":[],"name":"@am:string/effect_dots_name","filename":"assets/effects/dots2.xml","shader":{"type":"fragment","precision":"high","group":"0","code":"\n\n        //float rand(vec2 co)\n        //{\n        //    float a = 719.310;\n        //    float b = 178.233;\n        //    float c = 33758.5453;\n        //    float dt= dot(co.xy ,vec2(a,b));\n        //    float sn= mod(dt,3.14);\n        //    return fract(sin(sn) * c);\n        //}\n        //\n        //float rand_alt(vec2 co)\n        //{\n        //    float a = 317.541;\n        //    float b = 142.123;\n        //    float c = 31758.5362;\n        //    float dt= dot(co.xy ,vec2(a,b));\n        //    float sn= mod(dt,3.14);\n        //    return fract(sin(sn) * c);\n        //}\n        //\n        //vec2 rand2v(vec2 co) {\n        //    return vec2(rand(co),rand_alt(co));\n        //}\n\n\n        float random (in vec2 st) {\n            return fract(sin(dot(st.xy,\n                                 vec2(12.9898,78.233)))*\n                43758.5453123);\n        }\n\n        // Based on Morgan McGuire @morgan3d\n        // https://www.shadertoy.com/view/4dS3Wd\n        float noise (vec2 st) {\n            vec2 i = floor(st);\n            vec2 f = fract(st);\n\n            // Four corners in 2D of a tile\n            float a = random(i);\n            float b = random(i + vec2(1.0, 0.0));\n            float c = random(i + vec2(0.0, 1.0));\n            float d = random(i + vec2(1.0, 1.0));\n\n            vec2 u = f * f * (3.0 - 2.0 * f);\n\n            return mix(a, b, u.x) +\n                    (c - a)* u.y * (1.0 - u.x) +\n                    (d - b) * u.x * u.y;\n        }\n\n        float fbm (vec2 st, vec2 parallax, int octaveCount, float intens) {\n            // Initial values\n            float value = 0.;\n            float amplitude = 0.5;\n            float frequency = 0.;\n            //\n            // Loop of octaves\n            for (int i = 0; i < octaveCount; i++) {\n                value += amplitude * noise(st);\n                st *= 2.0;\n                st += parallax;\n                amplitude *= intens;\n            }\n            return value;\n        }\n\n\n        vec2 rand2v(vec2 co) {\n            return vec2(noise(co),noise(co+vec2(613.312,736.019)));\n        }\n\n        void main() {\n            vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);\n\n            vec2 st = acLayerNorm.st;\n            st.x *= acLayerSize.x/acLayerSize.y;\n            st -= vec2(0.5,0.5);\n            st -= (position*vec2(1.0,-1.0)/1000.0);\n            st /= (scale*0.07);\n\n            vec2 tile = floor(st);\n            vec2 tpart = fract(st);\n\n            float maxDist = 100.0;\n            vec2 nearestTile = vec2(0.0,0.0);\n            float nearest_k = 0.;\n\n            int densitySteps = int(max(1.0,density-10.0));\n            float threshold = min(1.0,density/11.0);\n\n            float actualPhase = phase * 6.28318;\n\n            for( int i=-1; i<=1; i++ ) {\n                for( int j=-1; j<=1; j++ ) {\n                    vec2 checkTileOffs = vec2(float(i),float(j));\n                    for( int k=0; k<densitySteps; k++ ) {\n                        vec2 p = rand2v(tile + vec2(523.135,621.265)*float(k) + checkTileOffs + vec2(123.215,272.055)*seed);\n                        p = 0.5 + (0.5*sin(actualPhase + 6.2831*p)*max(0.00001,slack));\n                        float dist = length(checkTileOffs + p - tpart);\n                        vec2 tileId = checkTileOffs + tile;\n                        float flk = float(k);\n                        float ck = random(tileId + vec2(flk,-flk) + vec2(541.117,163.713)*(seed+0.1));\n                        if( dist < maxDist && ck<=threshold ) {\n                            maxDist = dist;\n                            nearest_k = float(k);\n                            nearestTile = tileId;\n                        }\n                    }\n                }\n            }\n\n            float colorPct =  random(nearestTile + vec2(nearest_k,-nearest_k) + vec2(721.117,433.215)*seed);\n\n            float intensity = smoothstep(1.0-radius,1.0-(radius*(1.0-feather)),1.-maxDist);\n\n            //intensity *= random(nearestTile + vec2(nearest_k,-nearest_k) + vec2(541.117,163.713)*seed) > threshold ? 0.0 : 1.0;\n\n            vec4 over = texColor * fill;\n            vec4 rcolor = mix(color,color2,colorPct)*intensity*texColor.a;\n\n            vec4 result;\n            if( blendMode==1 ) {\n                result = vec4((texColor.rgb/texColor.a)*(rcolor.rgb/rcolor.a),1.0) * rcolor.a * texColor.a;\n                result = clamp(result,0.0,1.0);\n                result = result+(over*(1.0-result.a));\n                result = clamp(result,0.0,1.0);\n            } else if( blendMode==2 ) {\n                result = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-(rcolor.rgb/rcolor.a))),1.0) * rcolor.a * texColor.a;\n                result = clamp(result,0.0,1.0);\n                result = result+(over*(1.0-result.a));\n                result = clamp(result,0.0,1.0);\n            } else {\n                result = rcolor+(over*(1.0-rcolor.a));\n            }\n            gl_FragColor = mix(over,result,alpha);\n\n\n            //gl_FragColor = result+(over*(1.0-result.a));\n        }\n\n    "},"vertexShader":null,"script":null,"omsGraph252":true,"omsScript252":false,"omsGraphIntroduced252":true,"omsGraphBlocked252":null},"com.alightcreative.effects.edgeglow":{"id":"com.alightcreative.effects.edgeglow","category":"drawing","attributes":{"id":"com.alightcreative.effects.edgeglow","name":"@am:string/effect_edge_glow_name","desc":"@am:string/effect_edge_glow_desc","tags":"drawing,edge,neon","thumb":"thumb/glow.png","category":"drawing","experimental":"false"},"params":[{"type":"texture","id":"inputImg","label":"inputImg","srcType":"content","defaultValue":0,"min":null,"max":null,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"inputImg","srcType":"content"},"downsample":1},{"type":"texture","id":"edge","label":"edge","srcType":"buffer","defaultValue":0,"min":null,"max":null,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"edge","srcType":"buffer"},"downsample":1},{"type":"texture","id":"hblur","label":"hblur","srcType":"buffer","defaultValue":0,"min":null,"max":null,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"hblur","srcType":"buffer"},"downsample":1},{"type":"spinner","id":"smoothing","label":"@am:string/effect_param_smoothing","srcType":null,"defaultValue":5,"min":1,"max":10,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"smoothing","default":"5.","min":"1.","max":"10.","step":"0.01","label":"@am:string/effect_param_smoothing"},"downsample":1},{"type":"spinner","id":"threshold","label":"@am:string/effect_param_threshold","srcType":null,"defaultValue":0.7,"min":0,"max":1,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"threshold","default":"0.7","min":"0.","max":"1.","step":"0.01","label":"@am:string/effect_param_threshold"},"downsample":1},{"type":"switch","id":"invert","label":"@am:string/effect_param_invert","srcType":null,"defaultValue":false,"min":null,"max":null,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"invert","default":"false","label":"@am:string/effect_param_invert"},"downsample":1},{"type":"spinner","id":"strength","label":"@am:string/effect_param_blur","srcType":null,"defaultValue":0.1,"min":0,"max":2,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"strength","default":"0.1","min":"0.0","max":"2.0","step":"0.01","label":"@am:string/effect_param_blur"},"downsample":1},{"type":"spinner","id":"spread","label":"@am:string/effect_param_spread","srcType":null,"defaultValue":1.5,"min":0