           //vec2 pixel = vec2(1.,1.)/getTexSize(inputImg.size);\n            //vec2 layerPixel = vec2(1.,1.)/acLayerSize;\n            vec2 sampleCoord = mod(acLayerNorm + (offset * vec2(-1.,1.))/1000.0, 1.);\n            vec2 featherDist = (0.5-abs(mod(offset/1000.0,1.)-0.5)) * 2.0 * feather;\n            vec2 featherAmount = feather<0.0001 ? vec2(1.,1.) : smoothstep(vec2(0.,0.),featherDist,min(sampleCoord, vec2(1.,1.)-sampleCoord));\n            sampleCoord = (vec4(sampleCoord,0.0,1.0) * acLayerToScreen).xy;\n            vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);\n            float maskFactor;\n            if( mask ) {\n                maskFactor = texColor.a;\n            } else {\n                vec2 s = step(vec2(0.,0.), acLayerNorm) - step(vec2(1.,1.), acLayerNorm);\n                maskFactor = s.x * s.y;\n            }\n            vec4 overColor = texColor * (1.-(featherAmount.x * featherAmount.y));\n            //sampleCoord += pixel/2.;\n            gl_FragColor = overColor + (texture2DCv(inputImg.texture,sampleCoord) * maskFactor * (1. - overColor.a));\n        }\n\n    "}],"scripts":[],"name":"@am:string/effect_offset_name","filename":"assets/effects/offset.xml","category":"transform","shader":{"type":"fragment","group":"0","precision":"high","code":"\n\n        void main() {\n            //vec2 pixel = vec2(1.,1.)/getTexSize(inputImg.size);\n            //vec2 layerPixel = vec2(1.,1.)/acLayerSize;\n            vec2 sampleCoord = mod(acLayerNorm + (offset * vec2(-1.,1.))/1000.0, 1.);\n            vec2 featherDist = (0.5-abs(mod(offset/1000.0,1.)-0.5)) * 2.0 * feather;\n            vec2 featherAmount = feather<0.0001 ? vec2(1.,1.) : smoothstep(vec2(0.,0.),featherDist,min(sampleCoord, vec2(1.,1.)-sampleCoord));\n            sampleCoord = (vec4(sampleCoord,0.0,1.0) * acLayerToScreen).xy;\n            vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);\n            float maskFactor;\n            if( mask ) {\n                maskFactor = texColor.a;\n            } else {\n                vec2 s = step(vec2(0.,0.), acLayerNorm) - step(vec2(1.,1.), acLayerNorm);\n                maskFactor = s.x * s.y;\n            }\n            vec4 overColor = texColor * (1.-(featherAmount.x * featherAmount.y));\n            //sampleCoord += pixel/2.;\n            gl_FragColor = overColor + (texture2DCv(inputImg.texture,sampleCoord) * maskFactor * (1. - overColor.a));\n        }\n\n    "},"vertexShader":null,"script":null,"omsGraph252":true,"omsScript252":false,"omsGraphIntroduced252":true,"omsGraphBlocked252":null},"com.alightcreative.effects.ominodiff":{"id":"com.alightcreative.effects.ominodiff","category":"procedural","attributes":{"id":"com.alightcreative.effects.ominodiff","name":"@am:string/effect_omino_diffusion_name","desc":"@am:string/effect_omino_diffusion_desc","category":"procedural","tags":"channel,glitch,noise,distortion","thumb":"thumb/directionalblur.webp","experimental":"false","overdraw":"true","max-overdraw":"0.1"},"params":[{"type":"texture","id":"inputImg","label":"inputImg","srcType":"content","defaultValue":0,"min":null,"max":null,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"inputImg","srcType":"content"},"downsample":1},{"type":"spinner","id":"angle","label":"@am:string/effect_param_angle","srcType":null,"defaultValue":0,"min":0,"max":3600,"step":0.5,"valueType":"angle","choices":[],"rawAttributes":{"id":"angle","default":"0.0","min":"0.0","max":"3600.0","label":"@am:string/effect_param_angle","type":"angle","step":"0.5","ticks":"0,45,90,135,180,225,270,315,360","snap":"45,90,135"},"downsample":1},{"type":"spinner","id":"strength","label":"@am:string/effect_param_strength","srcType":null,"defaultValue":1,"min":0.01,"max":1,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"strength","default":"1.0","min":"0.01","max":"1.0","label":"@am:string/effect_param_strength","step":"0.01"},"downsample":1},{"type":"spinner","id":"steps","label":"@am:string/effect_param_steps","srcType":null,"defaultValue":35,"min":1,"max":200,"step":1,"valueType":null,"choices":[],"rawAttributes":{"id":"steps","default":"35.0","min":"1.0","max":"200.0","label":"@am:string/effect_param_steps","step":"1."},"downsample":1},{"type":"spinner","id":"errorWeight","label":"@am:string/effect_param_error_weight","srcType":null,"defaultValue":0.75,"min":0,"max":10,"step":0.001,"valueType":null,"choices":[],"rawAttributes":{"id":"errorWeight","default":".75","min":"0.0","max":"10.0","label":"@am:string/effect_param_error_weight","step":"0.001","snap":"1","ticks":"1"},"downsample":1},{"type":"spinner","id":"errorFalloff","label":"@am:string/effect_param_weight_falloff","srcType":null,"defaultValue":0,"min":0,"max":1,"step":0.01,"valueType":"percent","choices":[],"rawAttributes":{"id":"errorFalloff","default":"0.","min":"0.0","max":"1.0","label":"@am:string/effect_param_weight_falloff","step":"0.01","type":"percent"},"downsample":1},{"type":"selector","id":"palette","label":"@am:string/effect_param_palette","srcType":null,"defaultValue":2,"min":null,"max":null,"step":0.01,"valueType":null,"choices":[{"value":0,"label":"@am:string/effect_param_black_white"},{"value":1,"label":"@am:string/effect_param_rgb_posterize_2_levels"},{"value":2,"label":"@am:string/effect_param_rgb_posterize_3_levels"},{"value":3,"label":"@am:string/effect_param_rgb_posterize_4_levels"},{"value":4,"label":"@am:string/effect_param_gray_3_levels"},{"value":5,"label":"@am:string/effect_param_gray_4_levels"},{"value":6,"label":"@am:string/effect_param_cga_green_red_yellow"},{"value":7,"label":"@am:string/effect_param_cga_cyan_magenta_white"},{"value":8,"label":"@am:string/effect_param_cga_blue_cyan_magenta_white"},{"value":9,"label":"@am:string/effect_param_saturate_and_posterize"},{"value":12,"label":"@am:string/effect_param_custom_2color"},{"value":13,"label":"@am:string/effect_param_custom_3color"},{"value":14,"label":"@am:string/effect_param_custom_4color"},{"value":15,"label":"@am:string/effect_param_custom_5color"},{"value":16,"label":"@am:string/effect_param_custom_6color"}],"rawAttributes":{"id":"palette","default":"2","style":"dropdown","label":"@am:string/effect_param_palette"},"downsample":1},{"type":"spinner","id":"alpha","label":"@am:string/effect_param_alpha","srcType":null,"defaultValue":1,"min":0,"max":1,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"alpha","default":"1","min":"0","max":"1","step":"0.01","label":"@am:string/effect_param_alpha"},"downsample":1},{"type":"selector","id":"blendMode","label":"@am:string/effect_param_blendmode","srcType":null,"defaultValue":0,"min":null,"max":null,"step":0.01,"valueType":null,"choices":[{"value":0,"label":"@am:string/effect_param_normal"},{"value":1,"label":"@am:string/effect_param_multiply"},{"value":2,"label":"@am:string/effect_param_screen"}],"rawAttributes":{"id":"blendMode","default":"0","style":"dropdown","label":"@am:string/effect_param_blendmode"},"downsample":1},{"type":"color","id":"color1","label":"@am:string/effect_param_color1","srcType":null,"defaultValue":[0,0,0,1],"min":null,"max":null,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"color1","default":"#FF000000","label":"@am:string/effect_param_color1","alpha":"false","enabled":"false"},"downsample":1},{"type":"color","id":"color2","label":"@am:string/effect_param_color2","srcType":null,"defaultValue":[0.3333333333333333,0.3333333333333333,1,1],"min":null,"max":null,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"color2","default":"#FF5555FF","label":"@am:string/effect_param_color2","alpha":"false","enabled":"false"},"downsample":1},{"type":"color","id":"color3","label":"@am:string/effect_param_color3","srcType":null,"defaultValue":[0.3333333333333333,1,0.3333333333333333,1],"min":null,"max":null,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"color3","default":"#FF55FF55","label":"@am:string/effect_param_color3","alpha":"false","enabled":"false"},"downsample":1},{"type":"color","id":"color4","label":"@am:string/effect_param_color4","srcType":null,"defaultValue":[0.3333333333333333,1,1,1],"min":null,"max":null,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"color4","default":"#FF55FFFF","label":"@am:string/effect_param_color4","alpha":"false","enabled":"false"},"downsample":1},{"type":"color","id":"color5","label":"@am:string/effect_param_color5","srcType":null,"defaultValue":[1,0.3333333333333333,0.3333333333333333,1],"min":null,"max":null,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"color5","default":"#FFFF5555","label":"@am:string/effect_param_color5","alpha":"false","enabled":"false"},"downsample":1},{"type":"color","id":"color6","label":"@am:string/effect_param_color6","srcType":null,"defaultValue":[1,0.3333333333333333,1,1],"min":null,"max":null,"step":0.01,"valueType":null,"choices":[],"rawAttributes":{"id":"color6","default":"#FFFF55FF","label":"@am:string/effect_param_color6","alpha":"false","enabled":"false"},"downsample":1}],"uiLayout":[{"type":"section","attributes":{"text":"@am:string/effect_param_custom_palette"}}],"passes":[],"iterations":[],"shaders":[{"type":"fragment","group":"0","precision":"high","code":"\n\n        mat2 rot2(float a) {\n            float s = sin(a);\n            float c = cos(a);\n            return mat2(c,-s,s,c);\n        }\n\n        const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);\n\n        float colorDiff( vec3 a, vec3 b ) {\n            vec3 d = abs(a-b);\n            return d.r + d.g + d.b;\n        }\n\n        highp mat3 rgb2yuv = mat3(\n             0.299,     0.587,    0.114,\n            -0.14713,  -0.28886,  0.436,\n             0.615,    -0.51499, -0.10001\n        );\n        highp mat3 yuv2rgb = mat3(\n            1.0,  0.0,      1.13983,\n            1.0, -0.39465, -0.58060,\n            1.0,  2.03211,  0.0\n        );\n\n        void main() {\n\n            vec2 v = vec2(1.,0.) * rot2((180.0-angle) * 0.0174533);\n            //v.x *= acScreenSize.y / acScreenSize.x;\n            vec2 dv = v * strength / steps;\n            vec3 accumErr = vec3(0.);\n            vec4 outColor = vec4(0.);\n            for(float i=steps; i>=0.0; i -= 1.0 ) {\n                float pct = i/steps;\n                vec4 texColor = texture2DCv(inputImg.texture, acScreenNorm.st + dv*i);\n                vec3 baseColor = saturate((texColor.a < 0.001 ? vec3(0.) : texColor.rgb / texColor.a) + accumErr);\n                \n                vec3 matchColor;\n                if( palette == 0 ) { // Black & white\n                    float luminance = dot(baseColor, luminanceWeighting);\n                    matchColor = luminance < 0.5 ? vec3(0.) : vec3( 1. );\n                } else if( palette == 1 ) { // RGB 2-Level Posterize\n                    matchColor = floor(baseColor* 2.0);\n                } else if( palette == 2 ) { // RGB 3-Level Posterize\n                    matchColor = floor((baseColor + 0.25) * 2.0) / 2.0;\n                } else if( palette == 3 ) { // RGB 4-Level Posterize\n                    matchColor = floor((baseColor + 0.1666667) * 3.0) / 3.0;\n                } else if( palette == 4 ) { // Gray 3 levels\n                    float luminance = dot(baseColor, luminanceWeighting);\n                    float adjLum = floor((luminance + 0.25) * 2.0) / 2.0;\n                    matchColor = vec3(adjLum);\n                } else if( palette == 5 ) { // Gray 4 levels\n                    float luminance = dot(baseColor, luminanceWeighting);\n                    float adjLum = floor((luminance + 0.1666667) * 3.0) / 3.0;\n                    matchColor = vec3(adjLum);\n                } else if( palette == 6 ) { // CGA Green/Red/Yellow\n                    matchColor = floor(baseColor*2.0);\n                    matchColor.b = 0.;\n                } else if( palette == 7 ) { // CGA Cyan/Magenta/White\n                    matchColor = floor(baseColor*2.0);\n                    matchColor.b = matchColor.r > 0.1 || matchColor.g > 0.1 ? 1. : 0.;\n                } else if( palette == 8 ) { // CGA Blue/Cyan/Magenta/White\n                    matchColor = floor(baseColor*2.0);\n                    matchColor.b = 1.;\n                } else if( palette == 9 ) { // Saturate and Posterize\n                    vec3 yuv = baseColor * rgb2yuv;\n                    yuv.gb = (yuv.gb-0.5) * 2.0 + 0.5;\n                    yuv.r = floor((yuv.r + 0.166667)*3.0)/3.0;\n                    matchColor = vec3(yuv * yuv2rgb);\n                } else if( palette == 11 ) {\n                    matchColor = color1.rgb;\n                } else if( palette == 12 ) {\n                    float d1 = colorDiff(baseColor,color1.rgb);\n                    float d2 = colorDiff(baseColor,color2.rgb);\n                    float dmin = min(d1,d2);\n                    matchColor = dmin==d1 ? color1.rgb : color2.rgb;\n                } else if( palette == 13 ) {\n                    float d1 = colorDiff(baseColor,color1.rgb);\n                    float d2 = colorDiff(baseColor,color2.rgb);\n                    float d3 = colorDiff(baseColor,color3.rgb);\n                    float dmin = min(min(d1,d2),d3);\n                    matchColor =\n                        dmin==d1 ? color1.rgb :\n                        dmin==d2 ? color2.rgb :\n                        color3.rgb;\n                } else if( palette == 14 ) {\n                    float d1 = colorDiff(baseColor,color1.rgb);\n                    float d2 = colorDiff(baseColor,color2.rgb);\n                    float d3 = colorDiff(baseColor,color3.rgb);\n                    float d4 = colorDiff(baseColor,color4.rgb);\n                    float dmin = min(min(d1,d2),min(d3,d4));\n                    matchColor =\n                        dmin==d1 ? color1.rgb :\n                        dmin==d2 ? color2.rgb :\n                        dmin==d3 ? color3.rgb :\n                        color4.rgb;\n                } else if( palette