       //vec3 rgb = userColor.rgb;\n            for (int r=0; r<volsteps; r++) {\n                vec3 p=from+s*dir*.5;\n                p = abs(vec3(tile)-mod(p,vec3(tile*2.))); // tiling fold\n                float pa,a=pa=0.;\n                for (int i=0; i<iterations; i++) {\n                    p=abs(p)/dot(p,p)-formuparam; // the magic formula\n                    a+=abs(length(p)-pa); // absolute sum of average change\n                    pa=length(p);\n                }\n                float dm=max(0.,darkmatter-a*a*.001); //dark matter\n                a*=a*a; // add contrast\n                if (r>6) fade*=1.-dm; // dark matter, don't render near\n                //v+=vec3(dm,dm*.5,0.);\n                v+=fade;\n                //v+=vec3(pow(s,1. + rgb.r*3.),pow(s,1. + rgb.g*3.),pow(s,1. + rgb.b*3.))*a*brightness*fade; // coloring based on distance\n                v+=vec3(s,s*s,s*s*s*s)*a*brightness*fade; // coloring based on distance\n                fade*=distfading; // distance fading\n                s+=stepsize;\n            }\n            v=mix(vec3(0.,v.g,length(v)),v,saturation); //color adjust\n            gl_FragColor = vec4(v*.01,1.);\n        }\n\n    "}],"scripts":[],"name":"@am:string/effect_starfield_name","filename":"assets/effects/starfield2.xml","shader":{"type":"fragment","precision":"high","group":"0","code":"\n\n        //#define iterations 17\n        //#define formuparam 0.53\n        //\n        //#define volsteps 20\n        //#define stepsize 0.1\n        //\n        //#define zoom   0.800\n        //#define tile   0.850\n        //#define speed  0.010\n        //\n        //#define brightness 0.0015\n        //#define darkmatter 0.300\n        //#define distfading 0.730\n        //#define saturation 0.450\n\n        #define iterations 14\n        #define formuparam 0.53\n\n        #define volsteps 16\n        #define stepsize 0.1\n\n        //#define zoom   0.300\n        #define tile   0.850\n        //#define speed  0.010\n